import {renderLab,bindLab} from './labs.js?v=c3-4';
import {modules} from './content.js?v=c3-4';
import {diagrams,references} from './diagrams.js?v=c3-4';
import {buildBank,createSession,grade,score} from './engine.js?v=c3-4';
const ASSESSMENTS=true,LABS=true;
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='soma-cell-studio-v1';let saved={};try{saved=JSON.parse(localStorage.getItem(key)||'{}')||{};}catch{}
const bank=buildBank(modules,diagrams),state={page:'home',module:modules.some(m=>m.id===saved.module)?saved.module:modules[0].id,tab:'learn',lesson:0,diagram:0,target:0,labels:true,revealed:false,reference:0,recall:0,flip:false,glossary:0,query:'',filter:'all',stats:saved.stats&&typeof saved.stats==='object'?saved.stats:{},session:null,review:0,storageError:false};
let cleanupLab;
const mod=()=>modules.find(m=>m.id===state.module),ds=()=>diagrams[state.module]||[],rs=()=>references.filter(r=>r.section===state.module||r.section===mod().section||r.module===state.module);
function persist(){try{localStorage.setItem(key,JSON.stringify({module:state.module,stats:state.stats}));}catch{state.storageError=true;}}
const mastered=id=>bank.filter(q=>q.module===id&&state.stats[q.id]?.lastCorrect&&!state.stats[q.id]?.assisted).length;
function heading(k,t,d=''){return `<div class="main-heading"><div><p class="eyebrow">${esc(k)}</p><h1>${esc(t)}</h1></div>${d?`<span class="pill">${esc(d)}</span>`:''}</div>`;}
function pager(id,i,n){return `<div class="pager"><button data-page="${id}" data-delta="-1" ${i<=0?'disabled':''}>← Previous</button><span>${i+1} / ${n}</span><button data-page="${id}" data-delta="1" ${i>=n-1?'disabled':''}>Next →</button></div>`;}
function header(){return `<header class="app-header"><a class="brand" href="./" data-nav="home">soma<span>CELL STUDIO</span></a><div class="header-links"><button data-nav="home">Chapter map</button>${ASSESSMENTS?'<button data-nav="exam">Chapter exam</button>':''}<a href="../">Chapters 1–2 ↗</a><button data-nav="sources" aria-label="Sources and help">?</button></div></header>`;}
function sidebar(){return `<aside class="sidebar"><p class="eyebrow">THE CELLULAR LEVEL</p><nav aria-label="Chapter 3 modules">${modules.map(m=>`<button class="module-nav ${state.page==='module'&&m.id===state.module?'current':''}" data-module="${m.id}"><b>${esc(m.section)}</b>${esc(m.title)}</button>`).join('')}</nav><button data-nav="glossary">Cell dictionary ↗</button><div class="sidebar-bottom"><p>OPENSTAX · CHAPTER 03</p><p>Explore. Experiment. Recall.</p><a href="../">← Organs & body atlas</a></div></aside>`;}
function footer(){return `<footer class="footer"><span><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/3-introduction" target="_blank" rel="noopener">Access for free at openstax.org · Chapter 3</a> · CC BY-NC-SA 4.0</span><span>${state.storageError?'Storage unavailable; this session still works.':'Progress stays in this browser · Chapter 3 only'}</span></footer>`;}
function home(){return `${heading('SMALL STRUCTURES. EXTRAORDINARY POSSIBILITIES.','Life, from the inside.','6 connected modules')}<section class="hero"><div class="hero-copy"><p class="eyebrow">WELCOME TO CELL STUDIO</p><h2>One cell. A whole world to discover.</h2><p>Explore its structures. Experiment with its processes. Turn the cellular level of organization into something you can see, explain and remember.</p><div class="hero-actions"><button class="primary" data-module="${state.module}">Enter the studio →</button><button data-nav="${ASSESSMENTS?'exam':'glossary'}">${ASSESSMENTS?'Test the whole chapter':'Explore the vocabulary'}</button></div></div><div class="cell-emblem" aria-hidden="true"><i></i><i></i><i></i></div></section><div class="module-grid">${modules.map(m=>{const n=bank.filter(q=>q.module===m.id).length,good=mastered(m.id);return `<button class="module-card" data-module="${m.id}"><div class="card-top"><span class="eyebrow">SECTION ${esc(m.section)}</span><span>↗</span></div><h3>${esc(m.title)}</h3><p>${esc(m.tagline)}</p><div class="card-foot"><span>${good?`${good} / ${n} recalled`:`${m.lessons.length} lessons · ${(diagrams[m.id]||[]).length} ${(diagrams[m.id]||[]).length===1?'diagram':'diagrams'}`}</span><progress aria-label="${esc(m.title)} independently recalled questions" max="${n}" value="${good}"></progress></div></button>`;}).join('')}</div>`;}
function moduleView(){const m=mod(),tabs=[['learn','Learn'],['diagram','Diagram atlas'],['reference','Textbook'],...(LABS?[['lab','Experiment']]:[]),['recall','Recall cards'],...(ASSESSMENTS?[['practice','Practice']]:[])];return `${heading(`SECTION ${m.section} / CELLULAR ORGANIZATION`,m.title,`${m.lessons.length} lessons`)}<div class="tabs" aria-label="Module activities">${tabs.map(([id,n])=>`<button data-tab="${id}" aria-pressed="${state.tab===id}">${n}</button>`).join('')}</div>${state.tab==='diagram'?diagramView():state.tab==='reference'?referenceView():state.tab==='recall'?recallView():state.tab==='practice'?setup(false):state.tab==='lab'?'<section class="panel lab-container" id="lab-container"></section>':learnView()}`;}
function learnView(){const m=mod(),l=m.lessons[state.lesson];return `<div class="workspace"><section class="panel lesson"><label class="form-row small">Jump to lesson<select id="lesson-select">${m.lessons.map((item,i)=>`<option value="${i}" ${i===state.lesson?'selected':''}>${i+1}. ${esc(item.title)}</option>`).join('')}</select></label><h2>${esc(l.title)}</h2><p class="body">${esc(l.body)}</p>${pager('lesson',state.lesson,m.lessons.length)}</section><section class="panel lesson"><div class="tip"><b>Make it stick</b><p>${esc(l.analogy)}</p></div><div><p class="eyebrow">A COMMON MIX-UP</p><p class="trap">${esc(l.trap)}</p></div><div class="hero-actions"><button data-tab="diagram">See the structures ↗</button>${LABS?'<button data-tab="lab">Try the experiment ↗</button>':''}</div></section></div>`;}
function figure(d,{quiz=false,locate=false,target=-1,reveal=false}={}){const active=quiz?((!locate||reveal)?target:-1):state.target;return `<section class="panel figure-panel"><div class="panel-bar"><strong>${esc(d.title)}</strong>${quiz?'<span class="eyebrow">LABEL LAB</span>':`<label class="label-toggle"><input id="labels" type="checkbox" ${state.labels?'checked':''}>Labels</label>`}</div><div class="diagram-stage"><div class="diagram-wrap">${d.svg}${d.targets.map((t,i)=>`<button class="diagram-pin ${i===active?'active':''}" style="left:${t.x}%;top:${t.y}%" data-target="${i}" aria-label="${quiz||!state.labels?'Marker '+(i+1):esc(t.name)}" ${quiz&&(!locate||state.session?.answered)?'disabled':''}>${i+1}</button>`).join('')}</div></div>${!quiz?`<div class="diagram-key">${d.targets.map((t,i)=>`<button data-target="${i}" aria-pressed="${i===state.target}">${i+1}${state.labels?' · '+esc(t.name):''}</button>`).join('')}</div>`:''}<div class="figure-note">Teaching schematic · not to scale · OpenStax Chapter 3</div></section>`;}
function diagramView(){const views=ds(),d=views[state.diagram],t=d.targets[state.target];return `<div class="toolbar"><label class="small">Diagram <select id="diagram-select">${views.map((x,i)=>`<option value="${i}" ${i===state.diagram?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label><span class="small muted">Select a number.</span></div><div class="workspace">${figure(d)}<section class="panel lesson"><p class="eyebrow">STRUCTURE ${state.target+1} / ${d.targets.length}</p>${state.labels||state.revealed?`<h2>${esc(t.name)}</h2><p class="body">${esc(t.description)}</p>`:'<h2>Retrieve the name.</h2><p>Say its name and explain its role before revealing the answer.</p><button class="primary" data-action="reveal">Reveal this label</button>'}<p class="small muted">${esc(d.description)}</p><div class="pager"><button data-target="${(state.target+d.targets.length-1)%d.targets.length}">← Previous</button><span>${state.target+1} / ${d.targets.length}</span><button data-target="${(state.target+1)%d.targets.length}">Next →</button></div></section></div>`;}
function referenceView(){const refs=rs();if(!refs.length)return '<section class="panel lesson"><h2>Read the original section</h2><p>Use the OpenStax source link below to read this section.</p></section>';const r=refs[state.reference%refs.length];return `<section class="panel figure-panel" style="flex:1"><div class="panel-bar"><strong>${esc(r.title)}</strong><span class="small">Original · labels visible</span></div><div class="reference-stage"><img src="${esc(r.file)}" alt="${esc(r.caption||r.title)}"></div><div class="reference-caption">${esc(r.caption)} <span class="small">© Rice University · CC BY-NC-SA 4.0 · book page ${esc(r.page)}</span></div><div style="padding:9px 16px">${pager('reference',state.reference,refs.length)}</div></section>`;}
function recallView(){const ts=mod().terms,t=ts[state.recall];return `<section class="panel lesson" style="flex:1"><p class="eyebrow">ACTIVE RECALL · SAY IT BEFORE YOU REVEAL IT</p><div class="recall-face"><h2>${state.flip?esc(t.term):'Which term fits?'}</h2><p>${esc(t.definition)}</p>${state.flip?'<span class="answer">Connect the name to its meaning.</span>':'<button class="primary" data-action="flip">Reveal the term</button>'}</div>${pager('recall',state.recall,ts.length)}</section>`;}
function glossary(){const ts=modules.flatMap(m=>m.terms.map(t=>({...t,module:m.id,section:m.section}))).filter(t=>(state.filter==='all'||t.module===state.filter)&&`${t.term} ${t.definition}`.toLowerCase().includes(state.query.toLowerCase())).sort((a,b)=>a.term.localeCompare(b.term));const total=Math.max(1,Math.ceil(ts.length/6));state.glossary=Math.min(state.glossary,total-1);return `${heading('THE WORDS BEHIND THE STRUCTURES','Cell dictionary',`${ts.length} terms`)}<div class="glossary-controls"><input id="term-search" type="search" value="${esc(state.query)}" placeholder="Search a term or meaning…" aria-label="Search cell dictionary"><select id="term-filter" aria-label="Filter dictionary by module"><option value="all">All Chapter 3</option>${modules.map(m=>`<option value="${m.id}" ${state.filter===m.id?'selected':''}>${m.section} · ${esc(m.title)}</option>`).join('')}</select></div><div class="glossary-list">${ts.slice(state.glossary*6,state.glossary*6+6).map(t=>`<article class="term-card"><span class="eyebrow">SECTION ${esc(t.section)}</span><h3>${esc(t.term)}</h3><p>${esc(t.definition)}</p></article>`).join('')||'<p>No matching terms. Try another word.</p>'}</div>${pager('glossary',state.glossary,total)}`;}
function setup(exam){return `${exam?heading('CONNECT THE ENTIRE CHAPTER','Your cellular checkpoint.','Chapter 3 only'):''}<div class="setup-grid"><section class="panel lesson"><p class="eyebrow">${exam?'CHAPTER EXAM':'MODULE PRACTICE'}</p><h2>${exam?'Six topics. One connected picture.':'Build your recall.'}</h2><label class="form-row">Answer format<select id="format"><option value="mixed">Mixed: concepts, labels & locations</option><option value="choice">Multiple choice</option><option value="typed">Type the term or label</option><option value="locate">Locate on a diagram</option></select></label><label class="form-row">Session length<select id="count">${(exam?[30,60]:[12,24]).map(n=>`<option value="${n}">${n} questions</option>`).join('')}<option value="all">All available questions</option></select></label><p class="small muted">${exam?'Balanced across all six modules. Explanations appear after submission.':'Feedback after every answer. Hints count as assisted recall.'}</p><button class="primary" data-action="${exam?'exam':'practice'}">${exam?'Begin chapter exam':'Start practice'} →</button></section><section class="panel lesson"><h2>Understand it. Then retrieve it.</h2><p>Identify structures, connect them to their functions, and predict what happens when a process changes.</p><div class="tip"><b>Make your result meaningful</b><p>Say your reasoning before you answer. Study the explanation even when your answer is correct.</p></div><p class="small muted">${exam?bank.length:bank.filter(q=>q.module===state.module).length} questions available. A shorter pool uses all available questions. Scores are saved locally; unfinished sessions are not restored after a reload.</p></section></div>`;}
function start(exam=false,retry=null){const questions=retry||createSession(bank,{module:exam?null:state.module,exam,format:$('#format').value,count:$('#count').value==='all'?'all':Number($('#count').value)});if(!questions.length)return;state.session={exam,questions,index:0,records:[],answered:false,hint:false,draft:''};state.page='quiz';render();}
function quiz(){const s=state.session,q=s.questions[s.index],m=modules.find(x=>x.id===q.module),d=(diagrams[q.module]||[]).find(x=>x.id===q.diagram),r=s.records.at(-1);return `<div class="quiz-top"><span>${s.exam?'CHAPTER EXAM':'PRACTICE'} · ${esc(m.title)} · ${s.index+1} / ${s.questions.length}</span><button data-action="end">End session</button></div><progress class="quiz-progress" max="${s.questions.length}" value="${s.index}"></progress><h1 class="question-heading" tabindex="-1" id="question">${esc(q.prompt)}</h1><div class="workspace quiz-workspace">${d?figure(d,{quiz:true,locate:q.type==='locate',target:q.target,reveal:s.answered&&!s.exam}):`<section class="panel question-card"><span class="orb">${esc(m.section)}</span><p class="eyebrow">${q.type==='typed'?'RETRIEVE THE TERM':'REASON IT THROUGH'}</p><h2>${esc(m.title)}</h2><p class="muted">${s.exam?'Review explanations after submission.':'Pause and predict before answering.'}</p></section>`}<section class="panel lesson">${q.type==='choice'&&s.answered?`<div class="feedback">Your answer: <strong>${esc(r.value)}</strong></div>`:q.type==='choice'?`<div class="choices">${q.options.map((o,i)=>`<button data-answer="${i}" ${s.answered?'disabled':''} class="${s.answered&&!s.exam?(o===q.answer?'correct':r.value===o?'wrong':''):''}"><b>${String.fromCharCode(65+i)}</b>${esc(o)}</button>`).join('')}</div>`:q.type==='typed'?`<form id="answer-form" class="form-row"><label for="typed">Your answer</label><input id="typed" value="${esc(s.draft)}" placeholder="Type the term…" autocomplete="off" ${s.answered?'disabled':''}><button class="primary" ${s.answered?'disabled':''}>Check answer</button></form>`:'<p>Select a numbered structure on the diagram.</p>'}${!s.answered&&!s.exam?`<button data-action="hint">${s.hint?'Hint shown · assisted recall':'Show a hint'}</button>${s.hint?`<div class="feedback">${esc(q.explanation)}</div>`:''}`:''}${s.answered?`<div class="feedback ${s.exam?'':r.correct?'good':'bad'}" role="status"><b>${s.exam?'Answer recorded.':r.correct?(r.assisted?'Correct with help.':'Correct.'):'Review this one.'}</b>${!s.exam?`<p>${esc(q.answerText||q.answer)} — ${esc(q.explanation)}</p>`:'<p>Review your answer after submission.</p>'}</div><button class="primary" data-action="next">${s.index===s.questions.length-1?(s.exam?'Submit exam':'See results'):'Next question'} →</button>`:'<button data-action="skip">Skip question</button>'}</section></div>`;}
function submit(value){const s=state.session;if(!s||s.answered)return;const q=s.questions[s.index],correct=grade(q,value);s.records.push({q,value,correct,assisted:s.hint});s.answered=true;const prev=state.stats[q.id]||{attempts:0};state.stats[q.id]={attempts:prev.attempts+1,lastCorrect:correct,assisted:s.hint};persist();render();}
function results(){const s=state.session,r=s.records[state.review],n=score(s.records),q=r.q,value=q.type==='locate'&&typeof r.value==='number'?(diagrams[q.module]||[]).find(d=>d.id===q.diagram)?.targets[r.value]?.name:r.value;return `${heading('YOUR NEXT STEP IS CLEAR','Recall, then refine.',`${n.independent} / ${n.total} independently correct`)}<div class="toolbar"><div class="stats-row"><span class="score">${Math.round(n.independent/n.total*100)}%</span><span class="small muted">${n.assisted} assisted · ${n.missed} to revisit</span></div><div class="tabs"><button data-action="retry" ${n.missed?'':'disabled'}>Retry missed & assisted</button><button data-nav="home">Chapter map</button></div></div><div class="workspace"><section class="panel lesson"><p class="eyebrow">ANSWER ${state.review+1} · ${r.assisted?'ASSISTED':r.correct?'CORRECT':'REVIEW'}</p><h2>${esc(q.prompt)}</h2><p>Your answer: <strong>${esc(value)}</strong></p><p>Correct answer: <strong>${esc(q.answerText||q.answer)}</strong></p><p>${esc(q.explanation)}</p>${pager('review',state.review,s.records.length)}</section><section class="panel lesson"><p class="eyebrow">RECONNECT THE IDEA</p><h2>${esc(modules.find(m=>m.id===q.module).title)}</h2><p>Revisit the lesson or explore the structure before trying again.</p><button class="primary" data-action="review-topic">Study this topic ↗</button><div class="tip"><b>What your score means</b><p>Only correct answers without a hint count as independent recall. Skipped and assisted questions stay in your retry set.</p></div></section></div>`;}
function sourcesView(){return `${heading('THE THINKING BEHIND THE STUDIO','Sources & controls')}<section class="panel lesson source-box" style="flex:1"><h2>Built around your Chapter 3.</h2><p>OpenStax <em>Anatomy and Physiology 2e</em>, supplied 2026 edition. Chapter 3, PDF pages 101–144. Textbook figures © Rice University, CC BY-NC-SA 4.0. Original schematics and activities are educational adaptations, not to scale. No OpenStax endorsement is implied.</p><p><a href="https://openstax.org/books/anatomy-and-physiology-2e/pages/3-introduction" target="_blank" rel="noopener">Read the complete chapter ↗</a></p><p>Learn provides short lessons. Diagram atlas offers labels. Textbook shows original figures. Recall cards retrieve key terms.${LABS?' Experiment lets you change conditions and build processes.':''}${ASSESSMENTS?' Practice gives immediate feedback; Chapter exam holds it until submission.':''}</p><p>Tab moves through controls; Enter or Space selects. All activities have button or keyboard controls. Chapter 3 progress is stored separately in this browser.</p><button data-action="reset">Reset Chapter 3 progress</button></section>`;}
function leave(){return state.page!=='quiz'||confirm('Leave this unfinished session? Submitted answers remain saved.');}
function selectModule(id){if(!leave())return;state.module=id;state.page='module';state.session=null;state.tab='learn';state.lesson=state.diagram=state.target=state.reference=state.recall=0;state.revealed=state.flip=false;persist();render();}
function render(){cleanupLab?.();cleanupLab=null;const body=state.page==='home'?home():state.page==='module'?moduleView():state.page==='glossary'?glossary():state.page==='exam'?setup(true):state.page==='quiz'?quiz():state.page==='results'?results():sourcesView();$('#app').innerHTML=header()+`<div class="shell">${sidebar()}<main class="main" id="main"><select class="mobile-module" id="mobile-module" aria-label="Choose a Chapter 3 module"><option value="">Choose a module…</option>${modules.map(m=>`<option value="${m.id}" ${state.page==='module'&&m.id===state.module?'selected':''}>${m.section} · ${esc(m.title)}</option>`).join('')}</select>${body}${footer()}</main></div>`;bind();if(state.page==='module'&&state.tab==='lab'){const box=$('#lab-container');box.innerHTML=renderLab(state.module);cleanupLab=bindLab(box,state.module);}if(state.page==='quiz')$('#question')?.focus({preventScroll:true});}
function bind(){
 document.querySelectorAll('[data-module]').forEach(b=>b.onclick=()=>selectModule(b.dataset.module));$('#mobile-module')?.addEventListener('change',e=>{if(e.target.value)selectModule(e.target.value);});
 document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();if(!leave())return;state.page=b.dataset.nav;state.session=null;render();});
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.tab;render();});document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state[b.dataset.page]+=Number(b.dataset.delta);state.flip=false;render();});
 document.querySelectorAll('[data-target]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.target);if(state.page==='quiz')submit(i);else{state.target=i;state.revealed=false;render();}});
 $('#lesson-select')?.addEventListener('change',e=>{state.lesson=Number(e.target.value);render();});$('#labels')?.addEventListener('change',e=>{state.labels=e.target.checked;state.revealed=false;render();});$('#diagram-select')?.addEventListener('change',e=>{state.diagram=Number(e.target.value);state.target=0;state.revealed=false;render();});
 $('#term-filter')?.addEventListener('change',e=>{state.filter=e.target.value;state.glossary=0;render();});$('#term-search')?.addEventListener('input',e=>{state.query=e.target.value;state.glossary=0;render();$('#term-search').focus();});
 document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>submit(state.session.questions[state.session.index].options[Number(b.dataset.answer)]));$('#typed')?.addEventListener('input',e=>{state.session.draft=e.target.value;});$('#answer-form')?.addEventListener('submit',e=>{e.preventDefault();const value=$('#typed').value.trim();if(value)submit(value);});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{switch(b.dataset.action){case'reveal':state.revealed=true;render();break;case'flip':state.flip=true;render();break;case'practice':start();break;case'exam':start(true);break;case'hint':state.session.hint=true;render();break;case'skip':submit('Skipped');break;case'next':{const s=state.session;if(s.index===s.questions.length-1){state.page='results';state.review=0;}else{s.index++;s.answered=false;s.hint=false;s.draft='';}render();break;}case'end':if(confirm('End this session and mark unanswered questions as skipped?')){const s=state.session;for(let i=s.index+(s.answered?1:0);i<s.questions.length;i++)s.records.push({q:s.questions[i],value:'Skipped',correct:false,assisted:false});state.page='results';state.review=0;render();}break;case'retry':start(false,state.session.records.filter(r=>!r.correct||r.assisted).map(r=>r.q));break;case'review-topic':{const q=state.session.records[state.review].q;state.page='module';state.module=q.module;state.session=null;state.lesson=state.reference=state.recall=0;state.flip=state.revealed=false;state.diagram=Math.max(0,ds().findIndex(d=>d.id===q.diagram));state.target=q.target??0;state.labels=true;state.tab=q.diagram?'diagram':'learn';persist();render();break;}case'reset':if(confirm('Reset only Chapter 3 scores?')){state.stats={};persist();render();}break;}});
}
render();
